CREATE TABLE public.destinations (
 id text PRIMARY KEY,
 name text NOT NULL,
 category text NOT NULL,
 location text NOT NULL,
 description text NOT NULL,
 tagline text NOT NULL,
 note text NOT NULL,
 source text NOT NULL,
 image text NOT NULL DEFAULT '',
 map_query text NOT NULL,
 photo_alt text,
 photo_source text,
 photo_credit text,
 sort_order integer NOT NULL DEFAULT 0,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.destinations TO anon, authenticated;
GRANT ALL ON public.destinations TO service_role;
ALTER TABLE public.destinations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public destination catalogue is readable" ON public.destinations FOR SELECT TO anon, authenticated USING (true);
CREATE UNIQUE INDEX destinations_unique_name ON public.destinations (lower(btrim(name)));
CREATE FUNCTION public.touch_destination_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
REVOKE EXECUTE ON FUNCTION public.touch_destination_updated_at() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER destinations_updated_at BEFORE UPDATE ON public.destinations FOR EACH ROW EXECUTE FUNCTION public.touch_destination_updated_at();
INSERT INTO public.destinations (id,name,category,location,description,tagline,note,source,image,map_query,photo_alt,photo_source,photo_credit,sort_order)
SELECT r.id,r.name,r.category,r.location,r.description,r.tagline,r.note,r.source,r.image,r."mapQuery",r."photoAlt",r."photoSource",r."photoCredit",(r.ordinality-1)::integer
FROM jsonb_to_recordset($seed$[
{"id":"kodiveri","name":"Kodiveri Dam","category":"Dams & Rivers","location":"Kodiveri, near Gobichettipalayam","description":"A beautiful cascade across the Bhavani River, framed by greenery. A favourite escape for a relaxed day by the water.","tagline":"Waterfront escape","note":"Check current water releases and local access restrictions. Bathing may be prohibited during high flows.","source":"https://erode.nic.in/tourism/places-of-interest/","image":"/__l5e/assets-v1/76454968-efc8-455c-9498-f579d1b6687c/erode-kodiveri.jpg","mapQuery":"Kodiveri Dam, Kodiveri, near Gobichettipalayam, Tamil Nadu, India","ordinality":1},
{"id":"bannari","name":"Bannari Amman Temple","category":"Temples","location":"Bannari, near Sathyamangalam","description":"A revered Amman shrine at the forest foothills, where faith, tradition and the beauty of the hills come together.","tagline":"Sacred traditions","note":"Dress respectfully. Festival dates and visiting arrangements should be confirmed with the temple.","source":"https://erode.nic.in/religious-tourism/","image":"/__l5e/assets-v1/625066f4-26ea-4286-a5c4-4bdc605ed916/erode-bannari.jpg","mapQuery":"Bannari Amman Temple, Bannari, near Sathyamangalam, Tamil Nadu, India","ordinality":2},
{"id":"vellode","name":"Vellode Bird Sanctuary","category":"Nature & Wildlife","location":"Vellode, near Erode","description":"A peaceful wetland on Periyakulam Lake, home to resident birds and seasonal visitors. Slow down and listen to nature.","tagline":"Birdwatcher’s favourite","note":"Winter is generally rewarding for birdwatching. Carry binoculars and avoid disturbing nesting birds.","source":"https://erode.nic.in/tourism/places-of-interest/","image":"/__l5e/assets-v1/84f412ae-e6bf-42a2-b7eb-2aa1208c9559/erode-vellode.jpg","mapQuery":"Vellode Bird Sanctuary, Vellode, near Erode, Tamil Nadu, India","ordinality":3},
{"id":"bhavanisagar","name":"Bhavanisagar Dam","category":"Dams & Rivers","location":"Bhavanisagar, near Sathyamangalam","description":"An impressive earthen dam on the Bhavani River, with expansive reservoir scenery and a nearby public park.","tagline":"Reservoir views","note":"Confirm park access before visiting. Restricted dam areas are not open for casual exploration.","source":"https://erode.nic.in/water-bodies-dams/","image":"/__l5e/assets-v1/ed517e06-92cb-4d3d-b181-78d92cb3c986/erode-bhavanisagar.jpg","mapQuery":"Bhavanisagar Dam, Bhavanisagar, near Sathyamangalam, Tamil Nadu, India","ordinality":4},
{"id":"sangameshwarar","name":"Bhavani Sangameshwarar Temple","category":"Temples","location":"Kooduthurai, Bhavani","description":"An ancient Shiva temple beside the meeting of the Cauvery and Bhavani rivers, a cherished spiritual landmark of Kongu Nadu.","tagline":"Riverside heritage","note":"The Amudha river is part of religious tradition. Riverbank access depends on water levels.","source":"https://erode.nic.in/religious-tourism/","image":"/__l5e/assets-v1/795306c7-3611-4450-a00f-ad2e89dfb24e/erode-sangameshwarar.jpg","mapQuery":"Bhavani Sangameshwarar Temple, Kooduthurai, Bhavani, Tamil Nadu, India","ordinality":5},
{"id":"jamakkalam","name":"Bhavani Jamakkalam Weaving Heritage","category":"Heritage & Culture","location":"Bhavani","description":"Discover the colourful handwoven carpets of Bhavani and the skilled craft traditions passed down through generations.","tagline":"Living craft traditions","note":"This is a local craft tradition rather than a single ticketed attraction. Arrange workshop visits directly with artisans.","source":"https://erode.nic.in/rural-handy-crafts-tourism/","image":"/__l5e/assets-v1/3c004f15-f2ef-4794-b0d3-c3cfb30cd29e/erode-jamakkalam.jpg","mapQuery":"Bhavani Jamakkalam weaving Bhavani Tamil Nadu","ordinality":6},
{"id":"varattupallam","name":"Varattupallam Dam","category":"Dams & Rivers","location":"Near Anthiyur, Bargur foothills","description":"An irrigation reservoir near the Bargur hills, surrounded by rural scenery and forest-edge landscapes.","tagline":"A quieter escape","note":"Visitor access is subject to local restrictions. Keep away from forest areas and wildlife.","source":"https://erode.nic.in/water-bodies-dams/","image":"/__l5e/assets-v1/d55941c2-2b02-496b-9b21-6b26168d85a9/erode-varattupallam.jpg","mapQuery":"Varattupallam Dam, Near Anthiyur, Bargur foothills, Tamil Nadu, India","ordinality":7},
{"id":"kunderipallam","name":"Kunderipallam Dam","category":"Dams & Rivers","location":"Near Kongarpalayam, Gobichettipalayam region","description":"A reservoir nestled against the hills in northern Erode district, valued for irrigation and its scenic setting.","tagline":"Hill-framed waters","note":"Check access locally. Do not swim or enter restricted water-management areas.","source":"https://erode.nic.in/water-bodies-dams/","image":"/__l5e/assets-v1/4151ca97-179d-4ec2-b5a4-bab9ef5b865a/erode-kunderipallam.jpg","mapQuery":"Kunderipallam Dam, Near Kongarpalayam, Gobichettipalayam region, Tamil Nadu, India","ordinality":8},
{"id":"sathyamangalam","name":"Sathyamangalam Tiger Reserve","category":"Nature & Wildlife","location":"Sathyamangalam region","description":"A remarkable forest landscape linking the Western and Eastern Ghats, protecting tigers, elephants and rich biodiversity.","tagline":"Wild at heart","note":"Only authorised forest visits are permitted. Check current arrangements with the Forest Department; sightings are never guaranteed.","source":"https://erode.nic.in/eco-tourism/","image":"/__l5e/assets-v1/31732357-6025-43b7-8d35-e3a6d52e3b82/erode-sathyamangalam.jpg","mapQuery":"Sathyamangalam Tiger Reserve, Sathyamangalam region, Tamil Nadu, India","photoAlt":"Dhimbam hills in the Sathyamangalam region","ordinality":9},
{"id":"chennimalai","name":"Chennimalai Murugan Temple","category":"Temples","location":"Chennimalai","description":"A celebrated hilltop Murugan shrine with sweeping views of the Kongu countryside and a long devotional tradition.","tagline":"Hilltop serenity","note":"Plan for steps or confirm hill-road transport arrangements. Respect worship and photography restrictions.","source":"https://erode.nic.in/religious-tourism/","image":"/__l5e/assets-v1/dfc547e6-9afc-44a0-a478-5d60e968e2d6/erode-chennimalai.jpg","mapQuery":"Chennimalai Murugan Temple, Chennimalai, Tamil Nadu, India","ordinality":10},
{"id":"thindal","name":"Thindal Murugan Temple","category":"Temples","location":"Thindal, Erode","description":"A hill shrine dedicated to Lord Murugan on the western side of Erode, offering a peaceful pause above the city.","tagline":"Above the city","note":"Steps and uneven surfaces may affect accessibility. Confirm temple timings locally.","source":"https://erode.nic.in/religious-tourism/","image":"/__l5e/assets-v1/6de65c1a-edfb-4fc3-a9a4-009856d4afec/erode-thindal.jpg","mapQuery":"Thindal Murugan Temple, Thindal, Erode, Tamil Nadu, India","ordinality":11},
{"id":"magudeswarar","name":"Magudeswarar Temple","category":"Temples","location":"Kodumudi","description":"A historic temple complex by the Cauvery, with shrines associated with Shiva, Vishnu and Brahma.","tagline":"Cauvery-side devotion","note":"Dress respectfully and follow local instructions near the river.","source":"https://erode.nic.in/religious-tourism/","image":"/__l5e/assets-v1/5c5092b2-4e31-4db5-a4fb-afb0f33a252f/erode-magudeswarar.jpg","mapQuery":"Magudeswarar Temple, Kodumudi, Tamil Nadu, India","ordinality":12},
